def draw_VFXCharacterOutline(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, '基础', '基础', 0, None, True)
    if g0 is not None:
        kit.texture(g0, p, 'p_SludgeHeightTexture', '淤泥高度图', None, None)
        kit.texture(g0, p, 'p_DisappearTex', '淤泥消散噪声', None, None)
        kit.texture(g0, p, 'p_BlendTex', 'Blend Tex', 't_BlendTex', 'o_BlendTex')
        kit.texture(g0, p, 'p_MainTex2', 'Main Tex 2', 't_MainTex2', 'o_MainTex2')
        kit.texture(g0, p, 'p_InkSimulationResultA', 'Ink Simulation A', None, None)
        kit.texture(g0, p, 'p_InkSimulationResultB', 'Ink Simulation B', None, None)
        kit.texture(g0, p, 'p_FlowmapTex', 'Flowmap Tex', 't_FlowmapTex', 'o_FlowmapTex')
        kit.texture(g0, p, 'p_AirWallTex', 'AirWall Tex', 't_AirWallTex', 'o_AirWallTex')
        kit.texture(g0, p, 'p_EmissionTex', 'Emission Tex', 't_EmissionTex', 'o_EmissionTex')
