def draw_VFXCharacterWallhack(kit, layout, material, p):
    root = layout
    g0 = kit.group(root, p, '基础', '基础', 0, None, True)
    if g0 is not None:
        kit.texture(g0, p, 'p_SludgeHeightTexture', '淤泥高度图', None, None)
        kit.texture(g0, p, 'p_DisappearTex', '淤泥消散噪声', None, None)
